def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited
    supply of the given *coins*. If it's impossible, return -1.
    Classic unbounded knapsack / coin change DP.
    """
    # Edge case
    if amount == 0:
        return 0
    # Initialize DP array where dp[i] is min coins for amount i
    # Use amount+1 as sentinel (greater than any possible answer)
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # if we can use coin c, consider using it
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != amount + 1 else -1

