            x,y = stack.pop()
            if x<0 or x>=m or y<0 or y>=n:
                continue
            if visited[x][y] or grid[x][y]==0:
                continue
            visited[x][y]=True
            stack.append((x+1,y))
            stack.append((x-1,y))
            stack.append((x,y+1))
