    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each either an integer or one of '+', '-', '*', '/'.
    Returns integer result. Division truncates toward zero as in Python int(a/ b) behavior.
    """
    stack = []
    for t in tokens:
        if t in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division
                # Truncate toward zero
                if a * b < 0:
                    stack.append(- (abs(a) // abs(b)))
                else:
                    stack.append(a // b)
        else:
            stack.append(int(t))
    return stack[0] if stack else 0"}

