def solve(nums):
    # patience sorting O(n log n)
    import bisect
    tail = []
    for x in nums:
        # find position to replace
        idx = bisect.bisect_left(tail, x)
        if idx == len(tail):
            tail.append(x)
        else:
            tail[idx] = x
    return len(tail)

def solve(n):
    """Return the number of prime numbers strictly less than *n*.
    Uses Sieve of Eratosthenes.
    """
    if n <= 2:
        return 0
    sieve = bytearray(b'\x01') * n
    sieve[0:2] = b'\x00\x00'
    limit = int(n ** 0.5) + 1
    for p in range(2, limit):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:n:step] = b'\x00' * ((n - start - 1) // step + 1)
    return sum(sieve)

