            for j in range(k+1,n):
                m[i][j]=(m[i][j]*pivot - m[i][k]*m[k][j])//prev_pivot
        for i in range(k+1,n):
            m[i][k]=0
        prev_pivot=pivot
    return sign*m[n-1][n-1]

def det_recursive(mat):
    if not mat:
        return 1
    n=len(mat)
    if n==1:
        return mat[0][0]
    det=0
    for c in range(n):
        sub=[row[:c]+row[c+1:] for row in mat[1:]]
        det+=((-1)**c)*mat[0][c]*det_recursive(sub)
    return det

