def solve(n):
    """Return the count of prime numbers strictly less than n."""
    if n <= 2:
        return 0
    # Sieve of Eratosthenes up to n-1
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    import math
    for p in range(2, int(math.isqrt(n - 1)) + 1):
        if is_prime[p]:
            step = p
            start = p * p
            for multiple in range(start, n, step):
                is_prime[multiple] = False
    return sum(is_prime)

