def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search: O(n log n).
    """
    import bisect
    tail = []  # tail[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # find position to replace (first >= x) for strictly increasing -> use bisect_left
        i = bisect.bisect_left(tail, x)
        if i == len(tail):
            tail.append(x)
        else:
            tail[i] = x
    return len(tail)

