    Frequencies are sorted descending, ties broken alphabetically.
    Non‑hashable items in *words* are ignored. *k* is coerced to int if possible.
    If *k* is not a positive integer after conversion, an empty list is returned.
    """
    # Convert k to integer if possible
    try:
        k_int = int(k)
    except Exception:
        return []
    if k_int <= 0:
        return []
    # Count occurrences, ignoring unhashable items
    cnt = {}
    for w in words:
        try:
            cnt[w] = cnt.get(w, 0) + 1
        except Exception:
            # Skip items that cannot be used as dict keys
            continue
    # Sort by descending frequency then alphabetically (string representation fallback)
    # Use the item itself for alphabetical order; if incomparable, fallback to str
    def sort_key(item):
        word, freq = item
        return (-freq, word if isinstance(word, str) else str(word))
    sorted_items = sorted(cnt.items(), key=sort_key)
    return [word for word, _ in sorted_items[:k_int]]

