def solve(tokens):
    """Evaluate Reverse Polish Notation.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division truncating toward zero
                # Perform integer division with truncation toward zero without using float
                if b == 0:
                    # Division by zero is undefined; returning 0 for safety
                    res = 0
                else:
                    sign = -1 if (a < 0) ^ (b < 0) else 1
                    res = abs(a) // abs(b)
