def solve(matrix):
    if not matrix:
        return 1
    n=len(matrix)
    for row in matrix:
        if len(row)!=n:
            raise ValueError
    m=[list(row) for row in matrix]
    sign=1
    prev=1
    for k in range(n-1):
        if m[k][k]==0:
            swap=None
            for i in range(k+1,n):
                if m[i][k]!=0:
                    swap=i;break
            if swap is None:
                return 0
            m[k],m[swap]=m[swap],m[k]
            sign=-sign
        pivot=m[k][k]
        for i in range(k+1,n):
            for j in range(k+1,n):
                m[i][j]=(m[i][j]*pivot - m[i][k]*m[k][j])//prev
        for i in range(k+1,n):
            m[i][k]=0
        prev=pivot
    return sign*m[n-1][n-1]

def det_rec(mat):
    if not mat:
