def solve(n):
    """Return the number of primes strictly less than n.
    Handles non-integer or negative inputs by returning 0.
    Uses Sieve of Eratosthenes for efficiency.
    """
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

